    "id": "geo",
    "label": "Maps",
    "svg": "<svg version=\"1.1\" id=\"tree-geo\" width=\"100%\" xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\" x=\"0px\" y=\"0px\" viewBox=\"0 400 1508.3 802.4\" xml:space=\"preserve\" role=\"img\" aria-label=\"Decision tree for Maps data\">\n  <style type=\"text/css\">\n    .geost0{fill:none;stroke:#808285;stroke-width:3;stroke-linecap:square;stroke-miterlimit:10;}\n    .geost1{font-family:'Lato-Regular';}\n    .geost2{font-size:13px;}\n    .geost3{fill:#808285;}\n    .geost4{fill:#FFFFFF;stroke:#808285;stroke-width:3;stroke-linecap:square;stroke-miterlimit:10;}\n    .geost5{fill:none;stroke:#808285;stroke-width:3;stroke-miterlimit:10;}\n  </style>\n  <g id=\"Geo\">\n    <g>\n      <g>\n        <line class=\"geost0\" x1=\"751.2\" y1=\"1109.1\" x2=\"751.2\" y2=\"0\"></line>\n      </g>\n      <text transform=\"matrix(1 0 0 1 691.4728 1147.23)\"><tspan x=\"0\" y=\"0\" class=\"geost1 geost2\">BUBBLE</tspan><tspan x=\"20.3\" y=\"13\" class=\"geost1 geost2\">MAP</tspan></text>\n      <g>\n        <path class=\"geost3\" d=\"M803.6,1079.9c0,29-23.5,52.4-52.4,52.4s-52.4-23.5-52.4-52.4c0-29,23.5-52.4,52.4-52.4\n          S803.6,1051,803.6,1079.9z\"></path>\n        <g data-tip=\"Requires the latitude and longitude of each bubble, plus a numeric value for their size. Note that a categoric variable can be added, to control the color of the bubble for example.\" data-tip-image=\"/img/table/Map/coordAndValue.png\">\n          <a href=\"/graph/bubblemap.html\" data-chart=\"bubblemap\" aria-label=\"Bubble maps\"><image style=\"overflow:visible;\" width=\"114\" height=\"114\" xlink:href=\"/img/section/BubbleMapSmall.png\" transform=\"matrix(0.8522 0 0 0.8522 702.6083 1031.3705)\"></image></a>\n        </g>\n      </g>\n      <text transform=\"matrix(1 0 0 1 711.9479 1009.3174)\"><tspan x=\"0\" y=\"0\" class=\"geost1 geost2\">MAP</tspan><tspan x=\"-19.2\" y=\"13\" class=\"geost1 geost2\">HEXBIN</tspan></text>\n      <g>\n        <circle class=\"geost3\" cx=\"751.2\" cy=\"942\" r=\"52.4\"></circle>\n        <g data-tip=\"A list of coordinates. It is then possible to cut the space in several hexagons and count the number of dot per hexagon.ORA numeric value per region. Each region will be represented by an hexagon, which shape file must be provided as well.\" data-tip-image=\"/img/table/Map/hexbin.png\">\n          <a href=\"/graph/hexbinmap.html\" data-chart=\"hexbinmap\" aria-label=\"Hexbin Map\"><image style=\"overflow:visible;\" width=\"114\" height=\"114\" xlink:href=\"/img/section/MapHexbinSmall.png\" transform=\"matrix(0.8522 0 0 0.8522 702.6083 893.4605)\"></image></a>\n        </g>\n      </g>\n      <text transform=\"matrix(1 0 0 1 656.9191 871.4072)\" class=\"geost1 geost2\">CHOROPLETH</text>\n      <g>\n        <circle class=\"geost3\" cx=\"751.2\" cy=\"804.1\" r=\"52.4\"></circle>\n        <g data-tip=\"Requires a value (most often a numeric value) for each region to color. More over, you need the boundary coordinates of these regions.\" data-tip-image=\"/img/table/Map/RegionValue.png\">\n          <a href=\"/graph/choropleth.html\" data-chart=\"choropleth\" aria-label=\"Choropleth map\"><image style=\"overflow:visible;\" width=\"114\" height=\"114\" xlink:href=\"/img/section/ChoroplethSmall.png\" transform=\"matrix(0.8522 0 0 0.8522 702.6083 755.5505)\"></image></a>\n        </g>\n      </g>\n      <text transform=\"matrix(1 0 0 1 660.4225 733.498)\"><tspan x=\"-8\" y=\"0\" class=\"geost1 geost2\">CONNECTION</tspan><tspan x=\"50.5\" y=\"13\" class=\"geost1 geost2\">MAP</tspan></text>\n      <g>\n        <circle class=\"geost3\" cx=\"751.2\" cy=\"666.2\" r=\"52.4\"></circle>\n       <g data-tip=\"Requires the GPS coordinates of both the origin and the end of the connection. It is possible to provide a value for this connection as well.\" data-tip-image=\"/img/table/Map/coordStartEnd.png\">\n          <a href=\"/story/MapConnection.html\" data-chart=\"connection\" aria-label=\"Connection map\"><image style=\"overflow:visible;\" width=\"114\" height=\"114\" xlink:href=\"/img/section/ConnectedMapSmall.png\" transform=\"matrix(0.8522 0 0 0.8522 702.6083 617.6404)\"></image></a>\n        </g>\n      </g>\n      <text transform=\"matrix(1 0 0 1 711.9479 595.5889)\" class=\"geost1 geost2\">MAP</text>\n      <g>\n        <path class=\"geost3\" d=\"M803.6,528.3c0,29-23.5,52.4-52.4,52.4s-52.4-23.5-52.4-52.4c0-29,23.5-52.4,52.4-52.4\n          S803.6,499.3,803.6,528.3z\"></path>\n          <a href=\"/graph/map.html\" data-chart=\"map\" aria-label=\"Background Map\"><image style=\"overflow:visible;\" width=\"114\" height=\"114\" xlink:href=\"/img/section/MapSmall.png\" transform=\"matrix(0.8522 0 0 0.8522 702.6083 479.7304)\">\n        </image></a>\n      </g>\n    </g>\n  </g>\n  <g id=\"Time\">\n  </g>\n  <g id=\"Categorical\">\n  </g>\n  <g id=\"Cat_And_Num\">\n  </g>\n  <g id=\"Relational\">\n  </g>\n  <g id=\"Numeric_copy\">\n  </g>\n  <text transform=\"matrix(0.9999 -1.224000e-02 1.224000e-02 0.9999 87.5505 148.9814)\"><tspan x=\"720\" y=\"530\"><a class=\"mystory\" xlink:href=\"/story/MapConnection.html\">Story</a></tspan></text>\n  <text transform=\"matrix(0.9999 -1.224000e-02 1.224000e-02 0.9999 87.5505 148.9814)\"><tspan x=\"720\" y=\"670\"><a class=\"mystory\" xlink:href=\"/story/RegionWithValue.html\">Story</a></tspan></text>\n  <text transform=\"matrix(0.9999 -1.224000e-02 1.224000e-02 0.9999 87.5505 148.9814)\"><tspan x=\"720\" y=\"810\"><a class=\"mystory\" xlink:href=\"/story/GPSCoordWithoutValue.html\">Story</a></tspan></text>\n  <text transform=\"matrix(0.9999 -1.224000e-02 1.224000e-02 0.9999 87.5505 148.9814)\"><tspan x=\"720\" y=\"950\"><a class=\"mystory\" xlink:href=\"/story/GPSCoordWithValue.html\">Story</a></tspan></text>\n  </svg>"
